  ('Vesper', 'vesper', 'iba', 'https://iba-world.com/iba-cocktail/vesper/', 'IBA official cocktail · Contemporary Classics', array['Gin', 'Vodka']::text[], 'Cocktail glass', 'Lemon zest', 'Shake with ice and strain into a chilled cocktail glass.', '[{"amount":"45","unit":"ml","ingredient":"Gin"},{"amount":"15","unit":"ml","ingredient":"Vodka"},{"amount":"7.5","unit":"ml","ingredient":"Lillet Blanc"}]'::jsonb),
  ('Vieux Carré', 'vieux-carre', 'iba', 'https://iba-world.com/iba-cocktail/vieux-carre/', 'IBA official cocktail · The Unforgettables', array['Rye whiskey', 'Cognac']::text[], 'Cocktail glass', 'Orange zest and maraschino cherry', 'Stir well with ice in a mixing glass and strain into a chilled cocktail glass.', '[{"amount":"30","unit":"ml","ingredient":"Rye Whiskey"},{"amount":"30","unit":"ml","ingredient":"Cognac"},{"amount":"30","unit":"ml","ingredient":"Sweet Vermouth"},{"amount":"1","unit":"barspoon","ingredient":"Bénédictine"},{"amount":"2","unit":"dash","ingredient":"Peychaud''s Bitters"}]'::jsonb),
  ('Whiskey Sour', 'whiskey-sour', 'iba', 'https://iba-world.com/iba-cocktail/whiskey-sour/', 'IBA official cocktail · The Unforgettables', array['Bourbon']::text[], 'Cobbler glass', 'Half orange slice and maraschino cherry, optionally orange zest', 'Shake well with ice (harder if using egg white) and strain into a cobbler glass, or over ice in an old fashioned glass for on the rocks.', '[{"amount":"45","unit":"ml","ingredient":"Bourbon Whiskey"},{"amount":"25","unit":"ml","ingredient":"Fresh Lemon Juice"},{"amount":"20","unit":"ml","ingredient":"Sugar Syrup"},{"amount":"Few Drops of","unit":"","ingredient":"Egg White (Optional)"}]'::jsonb),
  ('White Lady', 'white-lady', 'iba', 'https://iba-world.com/iba-cocktail/white-lady/', 'IBA official cocktail · The Unforgettables', array['Gin']::text[], 'Cocktail glass', null, 'Shake well with ice and strain into a chilled cocktail glass.', '[{"amount":"40","unit":"ml","ingredient":"Gin"},{"amount":"30","unit":"ml","ingredient":"Triple Sec"},{"amount":"20","unit":"ml","ingredient":"Fresh Lemon Juice"}]'::jsonb);

insert into public.collections (slug, name, description, sort_order, built_in) values
  ('tiki', 'Tiki', 'Difford''s Guide Top 100 Tiki & Tropical Cocktails, plus our own tiki finds.', 1, true),
  ('classics', 'Classics', 'The IBA''s official cocktails: the Unforgettables, Contemporary Classics and New Era drinks.', 2, true),
  ('prohibition', 'Prohibition', 'Drinks created or first recorded during US Prohibition (1920–1933), each with its story and a source.', 3, true)
on conflict (slug) do nothing;

-- Tiki
insert into public.cocktail_collections (cocktail_id, collection_id)
select id, (select id from public.collections where slug = 'tiki') from public.cocktails where source in ('diffords', 'ours')
on conflict do nothing;
insert into public.cocktail_collections (cocktail_id, collection_id, note, note_url)
select m.cocktail_id, (select id from public.collections where slug = 'tiki'), m.note, m.note_url from (values
  ((select id from public.cocktails where slug = 'iba-tiki'), null, null),
  ((select id from public.cocktails where slug = 'pina-colada'), null, null),
  ((select id from public.cocktails where slug = 'planters-punch'), null, null)
) as m (cocktail_id, note, note_url)
on conflict do nothing;

