-- Prohibition
insert into public.cocktail_collections (cocktail_id, collection_id, note, note_url)
select m.cocktail_id, (select id from public.collections where slug = 'prohibition'), m.note, m.note_url from (values
  ((select id from public.cocktails where slug = 'bees-knees'), '1929: First printed in Paris in 1929 (Cocktails de Paris, credited to Frank Meier of the Ritz); the popular ''honey masked bathtub gin'' speakeasy story comes from Embury and is not supported.', 'https://www.diffordsguide.com/cocktails/recipe/2144/bees-knees'),
  ((select id from public.cocktails where slug = 'mary-pickford'), '1920s (printed 1928): Created at the Hotel Nacional in Havana for the film star during Prohibition and printed in Basil Woon''s 1928 When It''s Cocktail Time in Cuba; the bartender credit (Fred Kaufman or Eddie Woelke) is disputed.', 'https://www.diffordsguide.com/cocktails/recipe/1268/mary-pickford-cocktail'),
  ((select id from public.cocktails where slug = 'boulevardier'), '1927: Credited to American expat writer Erskine Gwynne at Harry MacElhone''s bar in Paris, first printed in Barflies and Cocktails (1927).', 'https://en.wikipedia.org/wiki/Boulevardier_(cocktail)'),
  ((select id from public.cocktails where slug = 'monkey-gland'), 'c. 1922–23: Harry MacElhone''s Paris drink named after Voronoff''s rejuvenation experiments; in his ABC of Mixing Cocktails from 1922/1923.', 'https://www.diffordsguide.com/cocktails/recipe/1349/monkey-gland'),
  ((select id from public.cocktails where slug = 'sidecar'), 'first printed 1922: First printed in 1922 (Vermeire and MacElhone), usually credited to Pat MacGarry of Buck''s Club, London, which opened in 1919; Embury''s claim that it dates to WWI makes the exact creation date disputed.', 'https://www.diffordsguide.com/cocktails/recipe/4791/sidecar'),
  ((select id from public.cocktails where slug = 'paradise'), '1922: First appeared in MacElhone''s 1922 Harry''s ABC of Mixing Cocktails and was refined in Craddock''s 1930 Savoy Cocktail Book.', 'https://www.diffordsguide.com/cocktails/recipe/1466/paradise'),
  ((select id from public.cocktails where slug = 'between-the-sheets'), '1920s (printed 1929): First printed in 1929 (Frank Shay) and linked to a speakeasy in a 1930 newspaper column; one claim credits the Berkeley Hotel, London, in 1921.', 'https://www.diffordsguide.com/cocktails/recipe/209/between-the-sheets'),
  ((select id from public.cocktails where slug = 'corpse-reviver-2'), 'first recorded 1930: ''Corpse reviver'' is an old name for a type of drink, but the No. 2 recipe (gin, Cointreau, Kina Lillet, lemon, absinthe) is first recorded in the 1930 Savoy Cocktail Book.', 'https://www.diffordsguide.com/cocktails/recipe/593/corpse-reviver-no2-savoy-recipe'),
  ((select id from public.cocktails where slug = 'angel-face'), 'first recorded 1930: First appears in Harry Craddock''s 1930 Savoy Cocktail Book.', 'https://www.diffordsguide.com/cocktails/recipe/521/angel-face'),
  ((select id from public.cocktails where slug = 'hanky-panky'), 'c. 1921: Made by Ada Coleman at the Savoy for actor Charles Hawtrey, probably around 1921, and printed in the 1930 Savoy book; Difford''s also says ''early 1900s'', so the date is not certain.', 'https://www.diffordsguide.com/cocktails/recipe/930/hanky-panky'),
  ((select id from public.cocktails where slug = 'white-lady'), 'c. 1929 (gin version): MacElhone''s 1919 White Lady used crème de menthe; today''s gin, Cointreau and lemon version appears around 1929 (credited to MacElhone, Craddock or Victor Cabrin) and was printed in the 1930 Savoy book.', 'https://www.diffordsguide.com/encyclopedia/512/cocktails/white-lady-cocktail'),
  ((select id from public.cocktails where slug = 'french-75'), '1927 (modern gin & Champagne form): The name dates to WWI (a different 1915 recipe with applejack and grenadine); the gin, lemon, sugar and Champagne version first appears in Judge Jr.''s 1927 Here''s How, a Prohibition-era US book.', 'https://www.diffordsguide.com/encyclopedia/1267/cocktails/french-75-cocktail-history'),
  ((select id from public.cocktails where slug = 'alexander'), 'first recorded 1930 (brandy version): The original 1916 Alexander used gin; the cognac version that IBA lists first appears in the 1930 Savoy Cocktail Book.', 'https://www.diffordsguide.com/encyclopedia/1072/cocktails/alexander-cocktails'),
  ((select id from public.cocktails where slug = 'remember-the-maine'), '1933 (printed 1939): Charles H. Baker recorded drinking it in Havana during the 1933 Cuban revolution, before repeal, and printed it in The Gentleman''s Companion (1939).', 'https://punchdrink.com/recipes/remember-the-maine/'),
  ((select id from public.cocktails where slug = 'mojito'), 'name first recorded 1931: The name ''Mojito'' first appears on Sloppy Joe''s Havana menu for 1931-32, though earlier forms were printed in 1927 and 1929 and the Draque goes back much further; American visitors during Prohibition are thought to have shaped it.', 'https://www.diffordsguide.com/g/1228/mojito-cocktail/mojito-cocktail-history'),
  ((select id from public.cocktails where slug = 'pisco-sour'), 'first recorded 1920: The earliest mention by name is in the Peruvian magazine Hogar (September 1920), tied to American expat Victor Morris''s Lima bar, but a similar unnamed recipe dates to 1903 and there is no link to US drinking.', 'https://en.wikipedia.org/wiki/Pisco_sour'),
  ((select id from public.cocktails where slug = 'daiquiri'), '1890s: Popularised by American mining engineer Jennings Cox in Cuba in the 1890s, it was refined in Havana bars like El Floridita for American drinkers who went there during Prohibition.', 'https://www.americanprohibitionmuseum.com/cocktails/daiquiri'),
  ((select id from public.cocktails where slug = 'honolulu-cocktail-no-1'), 'first recorded 1930: Gin with pineapple, orange and lemon juice and bitters, adapted from Harry Craddock''s 1930 Savoy Cocktail Book; no earlier source was found, but it may predate 1930.', 'https://www.diffordsguide.com/cocktails/recipe/2180/honolulu-cocktail-no-1')
) as m (cocktail_id, note, note_url)
on conflict do nothing;
